<script>
"use strict";
/* ============================================================
   Capacitor charge/discharge LED indicator
   Nodal analysis solved in-browser. Device models exactly as
   specified: battery = ideal source + 0.2 ohm internal,
   LED = off until Vf then I = (V - Vf)/10 (Vf = 2 V, unknown
   colour), rated 20 mA, burns out above 30 mA,
   switch = 0.001 ohm closed / open circuit,
   capacitor = open circuit at DC (companion model while transiently
   animating; state() reports the DC operating point).
   ============================================================ */

const VF_LED = 2.0, RS_LED = 10, BURN_I = 0.030;
const R_BATT_INT = 0.2, R_SWITCH = 0.001;

let mode = "fixed";            // "fixed" | "drawn"  — start in Fixed
let S1closed = false;
let ledBurnt = false;
const values = { B1: 5, R1: 1000, R2: 470, C1: 1 };   // as-drawn: 1000 mF = 1 F
let Vc = 0;                    // capacitor state (n3 relative to gnd)
let speed = 100;
let selectedNet = null;
const potPositions = {};

// latest transient solution snapshot (amps, sign = entering nodes[0])
const S = { Ib: 0, Ir1: 0, Is1: 0, Ic1: 0, Ir2: 0, Id1: 0 };
let nodeV = { vcc: 0, n2: 0, n3: 0, n4: 0, n5: 0, gnd: 0 };

const $ = id => document.getElementById(id);
const NS = "http://www.w3.org/2000/svg";
function el(tag, attrs) { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; }

/* ---------- linear solver (Gauss–Jordan, partial pivot) ---------- */
function solveLin(A, b) {
  const n = b.length;
  const M = A.map((row, i) => row.slice().concat(b[i]));
  for (let col = 0; col < n; col++) {
    let piv = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-12) M[piv][col] = 1e-12;
    const tmp = M[col]; M[col] = M[piv]; M[piv] = tmp;
    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = M[r][col] / M[col][col];
      for (let c = col; c <= n; c++) M[r][c] -= f * M[col][c];
    }
  }
  const x = new Array(n);
  for (let i = 0; i < n; i++) x[i] = M[i][n] / M[i][i];
  return x;
}

/* ---------- shared stamping helpers ---------- */
function solveBranches(nets, catNet, stampCap) {
  const idx = {}; nets.forEach((n, i) => idx[n] = i);
  const nN = nets.length;
  let ledOn = false, x = null;
  for (let iter = 0; iter < 60; iter++) {
    const G = Array.from({ length: nN }, () => new Array(nN).fill(0));
    const b = new Array(nN).fill(0);
    const g = (n1, n2, val) => {
      const gg = 1 / Math.max(val, 1e-3);
      const a = n1 === "gnd" ? -1 : idx[n1], c = n2 === "gnd" ? -1 : idx[n2];
      if (a >= 0) G[a][a] += gg;
      if (c >= 0) G[c][c] += gg;
      if (a >= 0 && c >= 0) { G[a][c] -= gg; G[c][a] -= gg; }
    };
    // leakage so floating (as-drawn) nets stay solvable
    for (let i = 0; i < nN; i++) G[i][i] += 1e-9;
    // battery: ideal source in series with 0.2 ohm (Norton: g=5 S, I = 5*V)
    const gb = 1 / R_BATT_INT;
    G[idx["vcc"]][idx["vcc"]] += gb;
    b[idx["vcc"]] += gb * values.B1;
    // R1 from vcc to n2
    g("vcc", "n2", values.R1);
    // switch
    if (S1closed) g("n2", "n3", R_SWITCH);
    // capacitor branch (or nothing, for the DC solve)
    stampCap(G, b, idx);
    // R2 from n3 to n4
    g("n3", "n4", values.R2);
    // LED from n4 to cathode net (burnt = open circuit)
    if (!ledBurnt && ledOn) {
      const gl = 1 / RS_LED;
      const a = idx["n4"];
      if (catNet === "gnd") { G[a][a] += gl; b[a] += VF_LED * gl; }
      else {
        const c = idx[catNet];
        G[a][a] += gl; G[c][c] += gl; G[a][c] -= gl; G[c][a] -= gl;
        b[a] += VF_LED * gl; b[c] -= VF_LED * gl;
      }
    }
    x = solveLin(G, b);
    const va = x[idx["n4"]];
    const vk = catNet === "gnd" ? 0 : x[idx[catNet]];
    const newOn = !ledBurnt && ((va - vk) > VF_LED);
    if (newOn === ledOn) break;
    ledOn = newOn;
  }
  return { x, idx };
}

/* ---------- DC steady state (capacitor = open circuit) ---------- */
function solveSteady() {
  const nets = mode === "fixed" ? ["vcc", "n2", "n3", "n4"] : ["vcc", "n2", "n3", "n4", "n5"];
  const catNet = mode === "fixed" ? "gnd" : "n5";
  const { x, idx } = solveBranches(nets, catNet, () => {});   // no capacitor branch at DC

  const V = n => n === "gnd" ? 0 : x[idx[n]];
  const vVcc = V("vcc"), vN2 = V("n2"), vN3 = V("n3"), vN4 = V("n4");
  const vN5 = catNet === "n5" ? V("n5") : 0;
  const vd = vN4 - vN5;

  const out = {
    vcc: vVcc, n2: vN2, n3: vN3, n4: vN4, n5: vN5, gnd: 0,
    Ib:  (values.B1 - vVcc) / R_BATT_INT,
    Ir1: (vVcc - vN2) / Math.max(values.R1, 1e-3),
    Is1: S1closed ? (vN2 - vN3) / R_SWITCH : 0,
    Ic1: 0,                                            // open circuit at DC
    Ir2: (vN3 - vN4) / Math.max(values.R2, 1e-3),
    Id1: (!ledBurnt && vd > VF_LED) ? (vd - VF_LED) / RS_LED : 0,
    vd
  };
  return out;
}

/* ---------- one transient step of the whole circuit (drives the animation) ---------- */
function compute(dt) {
  const nets = mode === "fixed" ? ["vcc", "n2", "n3", "n4"] : ["vcc", "n2", "n3", "n4", "n5"];
  const catNet = mode === "fixed" ? "gnd" : "n5";
  const VcPrev = Vc;
  const gc = values.C1 / Math.max(dt, 1e-9);

  const { x, idx } = solveBranches(nets, catNet, (G, b, id) => {
    G[id["n3"]][id["n3"]] += gc;
    b[id["n3"]] += gc * VcPrev;
  });

  const V = n => n === "gnd" ? 0 : x[idx[n]];
  const vVcc = V("vcc"), vN2 = V("n2"), vN3 = V("n3"), vN4 = V("n4");
  const vN5 = catNet === "n5" ? V("n5") : 0;

  S.Ic1 = gc * vN3 - gc * VcPrev;   // >0 while charging
  Vc = vN3;
  S.Ib  = (values.B1 - vVcc) / R_BATT_INT;   // current delivered out of + terminal
  S.Ir1 = (vVcc - vN2) / Math.max(values.R1, 1e-3);
  S.Is1 = S1closed ? (vN2 - vN3) / R_SWITCH : 0;
  S.Ir2 = (vN3 - vN4) / Math.max(values.R2, 1e-3);
  const vd = vN4 - vN5;
  S.Id1 = (!ledBurnt && vd > VF_LED) ? (vd - VF_LED) / RS_LED : 0;
  nodeV = { vcc: vVcc, n2: vN2, n3: vN3, n4: vN4, n5: vN5, gnd: 0 };

  if (!ledBurnt && S.Id1 > BURN_I) {
    ledBurnt = true;
    $("burntNote").hidden = false;
  }
  return vd;
}

function ledBrightness() { return ledBurnt ? 0 : Math.max(0, Math.min(1, S.Id1 / 0.020)); }

/* ---------- formatting ---------- */
function fmtV(v) { return (v < 0 ? "−" : "") + Math.abs(v).toFixed(2) + " V"; }
function fmtA(a) {
  const s = a < 0 ? "−" : "";
  const m = Math.abs(a);
  if (m < 1e-6) return "0.00 mA";
  if (m < 1e-3) return s + (m * 1e6).toFixed(0) + " µA";
  return s + (m * 1e3).toFixed(2) + " mA";
}
function fmtR(r) {
  if (r >= 1000) return ((r / 1000).toFixed(2).replace(/\.?0+$/, "")) + " kΩ";
  return r.toFixed(0) + " Ω";
}
function fmtC(c) {
  const trim = s => s.replace(/\.?0+$/, "");
  if (c >= 1) return trim(c.toFixed(2)) + " F";
  if (c >= 1e-3) return trim((c * 1e3).toFixed(2)) + " mF";
  return trim((c * 1e6).toFixed(1)) + " µF";
}

/* ---------- wire / segment geometry ---------- */
function pathD(pts) { return "M " + pts.map(p => p[0] + " " + p[1]).join(" L "); }
function poly(pts) {
  const cum = [0];
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i-1][0], pts[i][1] - pts[i-1][1]));
  return { pts, cum, len: cum[cum.length - 1] };
}
function pointAt(pl, d) {
  d = Math.max(0, Math.min(pl.len, d));
  const { pts, cum } = pl;
  let i = 1;
  while (i < cum.length - 1 && cum[i] < d) i++;
  const segLen = (cum[i] - cum[i - 1]) || 1;
  const t = (d - cum[i - 1]) / segLen;
  return [pts[i-1][0] + (pts[i][0] - pts[i-1][0]) * t, pts[i-1][1] + (pts[i][1] - pts[i-1][1]) * t];
}

function wireDefs() {
  const fixed = mode === "fixed";
  const defs = [
    { p: [[162,213],[162,173],[275,173]], net: "vcc", I: () => S.Ib  },
    { p: [[353,173],[392,173]],          net: "n2",  I: () => S.Ir1 },
    { p: [[440,173],[517,173]],          net: "n3",  I: () => S.Is1 },
    { p: [[517,173],[595,173]],          net: "n3",  I: () => S.Ir2 },
    { p: [[517,173],[517,223]],          net: "n3",  I: () => S.Ic1 },
    { p: [[698,173],[706,173],[706,250],[614,250],[614,300]], net: "n4", I: () => S.Ir2 },
    { p: [[517,257],[517,386]],          net: "gnd", I: () => S.Ic1 },
    { p: [[162,386],[162,291]],          net: "gnd", I: () => S.Ib  }
  ];
  if (fixed) {
    defs.push({ p: [[614,386],[517,386]], net: "gnd", I: () => S.Id1 });  // discharge return, right→left
    defs.push({ p: [[517,386],[162,386]], net: "gnd", I: () => S.Ib  });  // charge return, right→left
    defs.push({ p: [[614,352],[614,386]], net: "gnd", I: () => S.Id1 });
  } else {
    defs.push({ p: [[614,352],[614,386],[560,386]], net: "n5", I: () => S.Id1 });  // dangling cathode stub
    defs.push({ p: [[517,386],[162,386]], net: "gnd", I: () => S.Ib  });
    defs.push({ p: [[517,386],[540,386]], net: "gnd", I: () => 0     });          // dead-end stub
  }
  return defs;
}

let wireSegs = [];

function buildWires() {
  const lw = $("layerWires"), lh = $("layerWireHits"), lj = $("layerJunctions"), ld = $("layerDots");
  lw.innerHTML = ""; lh.innerHTML = ""; lj.innerHTML = ""; ld.innerHTML = "";
  wireSegs = [];

  for (const d of wireDefs()) {
    const D = pathD(d.p);
    const wp = el("path", { d: D, "class": "wire", "data-net": d.net });
    lw.appendChild(wp);
    const hp = el("path", { d: D, "class": "wire-hit", "data-net": d.net });
    hp.addEventListener("click", ev => { ev.stopPropagation(); selectNet(d.net); });
    lh.appendChild(hp);
    const pl = poly(d.p);
    const seg = { ...pl, I: d.I, offset: 0, dots: [] };
    const count = Math.ceil(pl.len / 34) + 1;
    for (let k = 0; k < count; k++) {
      const c = el("circle", { r: 2.6, "class": "flow-dot", opacity: 0 });
      ld.appendChild(c);
      seg.dots.push(c);
    }
    wireSegs.push(seg);
  }

  const junctions = mode === "fixed"
    ? [[517,173,"n3"],[517,386,"gnd"],[614,386,"gnd"]]
    : [[517,173,"n3"],[517,386,"gnd"]];
  for (const [x, y, net] of junctions) {
    const j = el("circle", { cx: x, cy: y, r: 4, "class": "junc", "data-net": net });
    lj.appendChild(j);
  }

  $("drawnOnly").style.display = mode === "drawn" ? "block" : "none";
  applyNetHighlight();
}

/* ---------- net selection ---------- */
function selectNet(net) {
  selectedNet = net;
  applyNetHighlight();
  $("netReadout").textContent = net
    ? "Net " + net + " · " + fmtV(nodeV[net] ?? 0)
    : "Click any wire to read its net voltage";
}
function applyNetHighlight() {
  document.querySelectorAll(".wire, .junc").forEach(e => {
    e.classList.toggle("net-hi", !!selectedNet && e.dataset.net === selectedNet);
  });
}

/* ---------- zigzag resistors ---------- */
function zigzag(x1, x2, y, amp, peaks) {
  const n = peaks * 2, dx = (x2 - x1) / n;
  let d = "M " + x1 + " " + y;
  for (let i = 1; i < n; i++) d += " L " + (x1 + dx * i).toFixed(2) + " " + (y + (i % 2 ? -amp : amp));
  d += " L " + x2 + " " + y;
  return d;
}
$("pR1").setAttribute("d", zigzag(275, 353, 173, 8, 5));
$("pR2").setAttribute("d", zigzag(595, 698, 173, 8, 6));

/* ---------- rendering ---------- */
const ledGlow = $("ledGlow"), triLED = $("triLED"), barLED = $("barLED"),
      burntMark = $("burntMark"), lever = $("lever");

function render(dtR) {
  // current dots
  for (const seg of wireSegs) {
    const I = seg.I();
    const a = Math.abs(I);
    const vis = a > 5e-5;
    const v = Math.max(0, Math.min(150, a * 9000));   // faster for more current
    if (vis && dtR > 0) {
      seg.offset = (seg.offset + Math.sign(I) * v * dtR) % seg.len;
      if (seg.offset < 0) seg.offset += seg.len;
    }
    const usable = Math.floor(seg.len / 34);
    for (let k = 0; k < seg.dots.length; k++) {
      const c = seg.dots[k];
      if (!vis || k > usable) { c.setAttribute("opacity", 0); continue; }
      const d = (seg.offset + k * 34) % seg.len;
      const [x, y] = pointAt(seg, d);
      c.setAttribute("cx", x.toFixed(1));
      c.setAttribute("cy", y.toFixed(1));
      c.setAttribute("opacity", 0.95);
    }
  }

  // LED appearance
  const b = ledBrightness();
  ledGlow.style.opacity = (b * 0.9).toFixed(3);
  if (ledBurnt) {
    triLED.setAttribute("fill", "#232323"); triLED.setAttribute("stroke", "#5A5A5A");
    barLED.setAttribute("stroke", "#5A5A5A");
    burntMark.style.display = "block";
    $("lD1").textContent = "D1 · burnt out";
    $("lD1").setAttribute("fill", "#FF8A8A");
  } else {
    triLED.setAttribute("fill", "rgba(255,95,95," + (0.15 + 0.75 * b).toFixed(3) + ")");
    triLED.setAttribute("stroke", "#C1C1FF");
    barLED.setAttribute("stroke", "#C1C1FF");
    burntMark.style.display = "none";
    $("lD1").textContent = mode === "drawn" ? "D1 · LED ?" : "D1 · LED";
    $("lD1").setAttribute("fill", "#9FC6DE");
  }

  // readouts
  $("roCap").textContent = fmtV(nodeV.n3);
  $("roLed").textContent = fmtA(S.Id1);
  $("roSw").textContent = S1closed ? "closed" : "open";
  if (selectedNet) $("netReadout").textContent = "Net " + selectedNet + " · " + fmtV(nodeV[selectedNet] ?? 0);
}

/* ---------- main loop ---------- */
let last = 0;
function frame(t) {
  requestAnimationFrame(frame);
  if (!last) last = t;
  const dtR = Math.min((t - last) / 1000, 0.05);
  last = t;
  const dtSim = dtR * speed;
  if (dtSim <= 0) { compute(1e-4); }
  else {
    const n = Math.min(200, Math.max(1, Math.ceil(dtSim / 0.02)));
    const h = dtSim / n;
    for (let i = 0; i < n; i++) compute(h);
  }
  render(dtR);
}

/* ---------- UI wiring ---------- */
function syncLabels() {
  $("vB1").textContent = values.B1.toFixed(1) + " V";
  $("vR1").textContent = fmtR(values.R1);
  $("vR2").textContent = fmtR(values.R2);
  $("vC1").textContent = fmtC(values.C1) + (mode === "drawn" ? " ?" : "");
  $("lB1").textContent = values.B1.toFixed(1) + " V";
  $("lR1").textContent = "R1 · " + fmtR(values.R1);
  $("lR2").textContent = "R2 · " + fmtR(values.R2);
  $("lC1").textContent = fmtC(values.C1) + (mode === "drawn" ? " ?" : "");
  $("sVB1").value = values.B1; $("sR1").value = values.R1; $("sR2").value = values.R2;
  $("sC1").value = Math.log10(values.C1);
}
function syncSwitchUI() {
  lever.style.transform = S1closed ? "rotate(0deg)" : "rotate(-27deg)";
}
function syncModeUI() {
  $("btnFixed").classList.toggle("active", mode === "fixed");
  $("btnFixed").setAttribute("aria-pressed", mode === "fixed");
  $("btnDrawn").classList.toggle("active", mode === "drawn");
  $("btnDrawn").setAttribute("aria-pressed", mode === "drawn");
  const tag = $("tag1");
  if (mode === "fixed") { tag.textContent = "repaired — rail joined"; tag.className = "tag tag-green"; }
  else { tag.textContent = "open circuit — LED dead"; tag.className = "tag tag-red"; }
}

$("sVB1").addEventListener("input", e => { values.B1 = +e.target.value; syncLabels(); });
$("sR1").addEventListener("input", e => { values.R1 = +e.target.value; syncLabels(); });
$("sR2").addEventListener("input", e => { values.R2 = +e.target.value; syncLabels(); });
$("sC1").addEventListener("input", e => { values.C1 = Math.pow(10, +e.target.value); syncLabels(); });
document.querySelectorAll(".speed-btn").forEach(btn => {
  btn.addEventListener("click", () => {
    speed = +btn.dataset.speed;
    $("vSpeed").textContent = btn.textContent;
    document.querySelectorAll(".speed-btn").forEach(b => b.classList.toggle("active", b === btn));
  });
});

$("btnFixed").addEventListener("click", () => window.__sim.setMode("fixed"));
$("btnDrawn").addEventListener("click", () => window.__sim.setMode("drawn"));
$("hitS1").addEventListener("click", () => window.__sim.setSwitch("S1", !S1closed));
$("schematic").addEventListener("click", () => selectNet(null));

// LED click: replace when burnt
$("hitD1").addEventListener("click", () => {
  if (ledBurnt) { ledBurnt = false; $("burntNote").hidden = true; }
});

/* ---------- hover tooltips ---------- */
const tooltip = $("tooltip"), holder = $("svgHolder");
const roleNames = { B1: "battery", R1: "resistor", R2: "resistor", S1: "switch", C1: "capacitor", D1: "LED" };
function partInfo(id) {
  const vNode = { B1: ["vcc", "gnd"], R1: ["vcc", "n2"], S1: ["n2", "n3"], C1: ["n3", "gnd"], R2: ["n3", "n4"], D1: ["n4", mode === "fixed" ? "gnd" : "n5"] }[id];
  const cur = { B1: S.Ib, R1: S.Ir1, S1: S.Is1, C1: S.Ic1, R2: S.Ir2, D1: S.Id1 }[id];
  const v = (nodeV[vNode[0]] ?? 0) - (nodeV[vNode[1]] ?? 0);
  return { cur, v };
}
document.querySelectorAll(".hit[data-part]").forEach(rect => {
  const id = rect.dataset.part;
  rect.addEventListener("mousemove", ev => {
    const { cur, v } = partInfo(id);
    let html = "<b>" + id + "</b> · " + roleNames[id] + "<br>Current " + fmtA(cur) + "<br>Voltage " + fmtV(v);
    if (id === "D1") {
      html += ledBurnt ? "<br>State burnt out (over 30 mA)" : "<br>Brightness " + Math.round(ledBrightness() * 100) + " % · " + (S.Id1 > 1e-4 ? "on" : "off");
    }
    if (id === "S1") html += "<br>State " + (S1closed ? "closed" : "open");
    if (id === "C1") html += "<br>Charge " + (values.C1 * Math.max(0, nodeV.n3)).toFixed(3) + " C";
    tooltip.innerHTML = html;
    const r = holder.getBoundingClientRect();
    tooltip.style.left = Math.min(ev.clientX - r.left + 14, r.width - 170) + "px";
    tooltip.style.top = (ev.clientY - r.top + 14) + "px";
    tooltip.style.display = "block";
  });
  rect.addEventListener("mouseleave", () => { tooltip.style.display = "none"; });
});

/* ---------- public API ----------
   state() reports the DC operating point (capacitor = open circuit,
   per the device-model definition), which is what the reference
   solver computes. The on-screen animation still runs the transient
   so the charge/discharge can be watched. */
window.__sim = {
  setMode(m) {
    if (m !== "fixed" && m !== "drawn") return;
    mode = m;
    Vc = 0;
    selectedNet = null;
    buildWires();
    syncModeUI();
    syncLabels();
    selectNet(null);
    compute(1e-4);
    render(0);
  },
  setSwitch(id, closed) {
    if (id === "S1") { S1closed = !!closed; syncSwitchUI(); compute(1e-4); render(0); }
  },
  setValue(id, value) {
    const v = Math.max(0, +value || 0);
    if (id === "B1") values.B1 = Math.min(v, 100);
    else if (id === "R1") values.R1 = v;
    else if (id === "R2") values.R2 = v;
    else if (id === "C1") values.C1 = Math.max(1e-6, v);
    else return;
    syncLabels(); compute(1e-4); render(0);
  },
  setPosition(id, p) {
    potPositions[id] = Math.max(0, Math.min(1, +p || 0));   // no potentiometers in this netlist
    compute(1e-4); render(0);
  },
  state() {
    const dc = solveSteady();                       // capacitor open at DC
    const nodes = mode === "fixed"
      ? { vcc: dc.vcc, n2: dc.n2, n3: dc.n3, n4: dc.n4, gnd: 0 }
      : { vcc: dc.vcc, n2: dc.n2, n3: dc.n3, n4: dc.n4, n5: dc.n5, gnd: 0 };
    const b = ledBurnt ? 0 : Math.max(0, Math.min(1, dc.Id1 / 0.020));
    const parts = {
      B1: { current: dc.Ib, voltage: dc.vcc },
      R1: { current: dc.Ir1, voltage: dc.vcc - dc.n2 },
      S1: { current: dc.Is1, voltage: dc.n2 - dc.n3, on: S1closed },
      C1: { current: dc.Ic1, voltage: dc.n3 },
      R2: { current: dc.Ir2, voltage: dc.n3 - dc.n4 },
      D1: { current: dc.Id1, voltage: dc.vd, on: dc.Id1 > 1e-4, brightness: b, burnt: ledBurnt }
    };
    return { mode, nodes, parts };
  }
};

/* ---------- init ---------- */
buildWires();
syncModeUI();
syncLabels();
syncSwitchUI();
compute(1e-4);
render(0);
requestAnimationFrame(frame);
</script>
